test_that("AMF follows OrdinaryDiffEqAMF", {
  algs <- list(Rosenbrock23 = Rosenbrock23, Rodas4 = Rodas4, Rodas5P = Rodas5P)
  for (r in amf_cases) {
    form <- sub("_.*", "", r$case)
    prob <- ODEProblem(if (form == "sym") amf_fun3() else amf_fun(if (form == "cb") "split" else form), amf_u0,
                       c(0, 2))
    alg <- AMF(algs[[r$alg]], autodiff = AutoFiniteDiff())
    opts <- if (grepl("adaptive", r$case)) list(reltol = 1e-6, abstol = 1e-8) else list(dt = 1 / 32, adaptive = FALSE)
    if (form == "cb") opts <- c(opts, list(callback = amf_cb, tstops = 0.5))
    sol <- do.call(solve, c(list(prob, alg), opts))
    st <- sol$stats
    lab <- paste(r$alg, r$case)
    expect_equal(c(length(sol$t), st$nf, st$njacs, st$nw, st$nsolve, st$naccept, st$nreject), r$stats, label = lab)
    expect_equal(sol$u[[length(sol$u)]], r$u, tolerance = 1e-12, label = lab)
  }
})

test_that("the AMF operators and SciMLOpFactorization", {
  fun <- amf_fun("split")
  expect_s3_class(fun, "ODEFunction")
  expect_equal(fun$sparsity, amf_AA)
  u <- c(0.3, -0.2, 0.5, 0.1)
  g <- 0.05
  W <- update_coefficients(fun$W_prototype, u, NULL, 0, gamma = g)
  J2 <- amf_upd2(NULL, u, NULL, 0)
  expect_equal(as.matrix(W), -((diag(4) - g * amf_A1) %*% (diag(4) - g * J2)) / g, tolerance = 1e-14)
  We <- update_coefficients(amf_fun("jac")$W_prototype, u, NULL, 0, gamma = g)
  expect_equal(as.matrix(We), amf_A1 + J2 - diag(4) / g, tolerance = 1e-14)
  b <- c(1, -2, 0.5, 3)
  for (L in list(W, We)) {
    x <- solve(LinearProblem(L, b), SciMLOpFactorization())
    expect_equal(x$retcode, "Success")
    expect_equal(x$u, solve(as.matrix(L), b), tolerance = 1e-13)
    expect_equal(solve(LinearProblem(L, b))$u, x$u, tolerance = 1e-13)
  }
  cache <- init(LinearProblem(W, b), SciMLOpFactorization())
  expect_equal(solve_integrator(cache)$u, solve(as.matrix(W), b), tolerance = 1e-13)
  cache$A <- We
  expect_equal(solve_integrator(cache)$u, solve(as.matrix(We), b), tolerance = 1e-13)
  # the exact operator of a single Jacobian and prebuilt factors
  J <- MatrixOperator(rbind(c(-1, 2), c(0.5, -3)))
  W1 <- update_coefficients(AMFOperator(J), gamma = 0.2)
  expect_equal(as.matrix(W1), as.matrix(J) - diag(2) / 0.2, tolerance = 1e-14)
  W2 <- update_coefficients(AMFOperator(factors = list(IdentityOperator(2) - 0.2 * J)), gamma = 0.2)
  expect_equal(as.matrix(W2), as.matrix(W1), tolerance = 1e-14)
  # a tensor product factorizes its two factors
  T2 <- TensorProductOperator(MatrixOperator(rbind(c(2, 1), c(1, 3))),
                              MatrixOperator(rbind(c(4, 0, 1), c(0, 5, 0), c(2, 0, 6))))
  b6 <- c(1, -2, 0.5, 3, 0.25, -1)
  expect_equal(solve(LinearProblem(T2, b6), SciMLOpFactorization())$u, solve(as.matrix(T2), b6), tolerance = 1e-14)
})

test_that("AMF reports invalid operators and problems", {
  J1 <- MatrixOperator(amf_A1)
  expect_error(build_amf_function(amf_f, jac = amf_A1), "jac must be an AbstractSciMLOperator")
  expect_error(build_amf_function(amf_f, jac = MatrixOperator(matrix(1, 2, 3))), "jac must be square")
  expect_error(build_amf_function(amf_f, jac = J1, split = list()), "split must contain at least one operator")
  expect_error(build_amf_function(amf_f, jac = J1, split = list(J1, MatrixOperator(diag(3)))),
               "all split operators must have the same square size")
  expect_error(build_amf_function(amf_f, jac = J1, split = list(MatrixOperator(diag(3)))),
               "split operators must have the same size as jac")
  expect_error(build_amf_function(amf_f, jac = J1, split = list(J1), amf_factors = list(J1, J1)),
               "split and amf_factors must contain the same number of operators")
  expect_error(build_amf_function(amf_f, jac = J1, amf_factors = list(MatrixOperator(diag(2)))),
               "amf_factors must have the same size as jac")
  expect_error(AMFOperator(list(MatrixOperator(matrix(1, 2, 3)))), "split operators must be square")
  expect_error(AMF(Tsit5), "AMF\\(\\) wraps a Rosenbrock method")
  expect_error(solve(ODEProblem(amf_f, amf_u0, c(0, 1)), AMF(Rodas5P)), "build_amf_function")
})
